<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api/admin';const rows=ref<any[]>([]),visible=ref(false),selected=ref<any>();const filters=reactive({objectType:'',operationType:''});async function load(){try{rows.value=await api.logs(filters)as any[]}catch(e:any){ElMessage.error(e.message)}}function detail(row:any){selected.value=row;visible.value=true}function pretty(v:string){try{return JSON.stringify(JSON.parse(v),null,2)}catch{return v||'—'}}onMounted(load);</script>
<template><div class="page"><div class="page-heading"><div><h1>操作日志</h1><p>关键人工操作的操作人、时间、对象和修改前后数据。</p></div></div><div class="filter-bar"><el-input v-model="filters.objectType" placeholder="对象类型" clearable/><el-input v-model="filters.operationType" placeholder="操作类型" clearable/><el-button @click="load">查询</el-button></div><div class="table-card"><el-table :data="rows"><el-table-column prop="createdAt" label="操作时间" min-width="170"/><el-table-column prop="operatorName" label="操作人" width="110"/><el-table-column prop="operationType" label="操作类型" min-width="190"/><el-table-column prop="objectType" label="对象" width="150"/><el-table-column prop="objectId" label="对象ID" width="110"/><el-table-column prop="remark" label="备注" min-width="220"/><el-table-column label="操作" width="90"><template #default="s"><el-button link type="primary" @click="detail(s.row)">详情</el-button></template></el-table-column></el-table></div><el-drawer v-model="visible" title="操作日志详情" size="620"><template v-if="selected"><h4>修改前</h4><pre>{{pretty(selected.beforeData)}}</pre><h4>修改后</h4><pre>{{pretty(selected.afterData)}}</pre></template></el-drawer></div></template>
<style scoped>pre{white-space:pre-wrap;word-break:break-all;background:#f7f7f8;border:1px solid #eee;border-radius:6px;padding:14px;font:12px/1.7 Consolas,monospace}</style>

